/**
 * Turns the city map drawing into code.
 *
 *   pnpm map:sync                     regenerate from design/map/permitopolis-map.svg
 *   pnpm map:sync path/to/new.svg     copy a new export over the source first, then regenerate
 *   pnpm map:sync --check             write nothing; fail if the generated files are stale
 *
 * Reads   design/map/permitopolis-map.svg   the drawing (the source of truth)
 *         styles/map.css                    the name of every color the drawing may use
 * Writes  components/map/art/layers.generated.tsx   one React component per layer
 *         lib/data/mapGeometry.generated.ts         where each space, street and node is
 *
 * What the drawing has to keep for the app to find its way around:
 *  - one top-level <g id="layer-..."> per layer;
 *  - a <rect id> with data-label in #layer-permit-spaces for every space in lib/data/inventory.ts;
 *  - a <path id> with data-nodes in #layer-permit-streets for every segment in lib/data/streets.ts;
 *  - colors written as six-digit hex, each named in styles/map.css.
 */
import { copyFileSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, relative, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { JSDOM } from "jsdom";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const SOURCE = join(ROOT, "design/map/permitopolis-map.svg");
const PALETTE = join(ROOT, "styles/map.css");
const LAYERS_OUT = join(ROOT, "components/map/art/layers.generated.tsx");
const GEOMETRY_OUT = join(ROOT, "lib/data/mapGeometry.generated.ts");

const HEADER = [
  "// Generated by scripts/sync-map.mjs from design/map/permitopolis-map.svg.",
  "// Do not edit by hand: change the drawing, then run `pnpm map:sync`.",
].join("\n");

const problems = [];

/* ---------- palette ---------- */

/** hex (lowercase) -> token name, from the `--map-*: #rrggbb;` lines of styles/map.css. */
function readPalette(css) {
  const byHex = new Map();
  for (const match of css.matchAll(/--(map-[a-z0-9-]+):\s*(#[0-9a-fA-F]{6})\s*;/g)) {
    const hex = match[2].toLowerCase();
    if (!byHex.has(hex)) byHex.set(hex, match[1]);
  }
  return byHex;
}

/* ---------- layers: SVG -> JSX ---------- */

const DRAWN = new Set(["g", "rect", "path", "circle", "text"]);
/** Left out of the JSX: ids would repeat when a page shows two maps, and text uses the app's font. */
const DROPPED = new Set(["id", "font-family"]);

function describe(el) {
  const id = el.getAttribute("id") ?? el.closest("[id]")?.getAttribute("id");
  return id ? `<${el.tagName} id="${id}">` : `<${el.tagName}>`;
}

function camel(name) {
  return name.replace(/-([a-z])/g, (_, letter) => letter.toUpperCase());
}

function colorClass(el, attribute, value, palette) {
  if (value === "none") return `${attribute}-none`;
  const token = /^#[0-9a-fA-F]{6}$/.test(value) ? palette.get(value.toLowerCase()) : undefined;
  if (!token) {
    problems.push(
      /^#[0-9a-fA-F]{6}$/.test(value)
        ? `${describe(el)} uses ${attribute} ${value}, which has no name in styles/map.css. Add a --map-* line for it.`
        : `${describe(el)} uses ${attribute} "${value}". Write colors as six-digit hex.`,
    );
    return `${attribute}-none`;
  }
  return `${attribute}-${token}`;
}

function toJsx(el, palette, indent) {
  const tag = el.tagName;
  if (!DRAWN.has(tag)) {
    problems.push(`${describe(el)} is a <${tag}>, which the sync does not know how to draw.`);
    return "";
  }
  const classes = [];
  const attributes = [];
  for (const { name, value } of Array.from(el.attributes)) {
    if (DROPPED.has(name) || name.startsWith("data-")) continue;
    if (name === "fill" || name === "stroke") classes.push(colorClass(el, name, value, palette));
    else attributes.push(`${camel(name)}=${JSON.stringify(value)}`);
  }
  if (classes.length > 0) attributes.unshift(`className="${classes.join(" ")}"`);
  const open = [tag, ...attributes].join(" ");

  if (tag === "text") return `${indent}<${open}>{${JSON.stringify(el.textContent ?? "")}}</text>`;
  const children = Array.from(el.children);
  if (children.length === 0) return `${indent}<${open} />`;
  const inner = children.map((child) => toJsx(child, palette, `${indent}  `)).filter(Boolean);
  return [`${indent}<${open}>`, ...inner, `${indent}</${tag}>`].join("\n");
}

function componentName(layerId) {
  return `${layerId
    .split("-")
    .map((part) => part[0].toUpperCase() + part.slice(1))
    .join("")}Layer`;
}

function buildLayers(svg, palette) {
  const layers = Array.from(svg.children).filter((el) => el.tagName === "g");
  const ids = [];
  const components = [];
  for (const layer of layers) {
    const id = layer.getAttribute("id") ?? "";
    if (!id.startsWith("layer-")) {
      problems.push(`A top-level group is named "${id}". Every top-level group needs an id that starts with "layer-".`);
      continue;
    }
    const layerId = id.slice("layer-".length);
    ids.push(layerId);
    components.push(
      [`function ${componentName(layerId)}() {`, "  return (", toJsx(layer, palette, "    "), "  );", "}"].join("\n"),
    );
  }
  return [
    HEADER,
    "",
    "/** The drawing's layers, bottom to top. */",
    `export const MAP_LAYER_IDS = [${ids.map((id) => JSON.stringify(id)).join(", ")}] as const;`,
    "",
    "export type MapLayerId = (typeof MAP_LAYER_IDS)[number];",
    "",
    components.join("\n\n"),
    "",
    "export const MAP_LAYERS: Record<MapLayerId, () => React.JSX.Element> = {",
    ...ids.map((id) => `  ${JSON.stringify(id)}: ${componentName(id)},`),
    "};",
    "",
  ].join("\n");
}

/* ---------- geometry ---------- */

const round = (value) => Math.round(value * 10) / 10;

function number(el, attribute) {
  const value = Number(el.getAttribute(attribute));
  if (!Number.isFinite(value)) problems.push(`${describe(el)} has no usable ${attribute}.`);
  return value;
}

/** Points along a path, close enough together to measure it. Absolute M, L, H, V, Q and C only. */
function samplePath(el) {
  const d = el.getAttribute("d") ?? "";
  const points = [];
  let x = 0;
  let y = 0;
  const STEPS = 48;
  for (const [, command, rest] of d.matchAll(/([A-Za-z])([^A-Za-z]*)/g)) {
    const n = rest.trim().split(/[\s,]+/).filter(Boolean).map(Number);
    if (command === "M" || command === "L") {
      for (let i = 0; i + 1 < n.length; i += 2) points.push({ x: (x = n[i]), y: (y = n[i + 1]) });
    } else if (command === "H") {
      for (const value of n) points.push({ x: (x = value), y });
    } else if (command === "V") {
      for (const value of n) points.push({ x, y: (y = value) });
    } else if (command === "Q") {
      for (let i = 0; i + 3 < n.length; i += 4) {
        const [cx, cy, ex, ey] = n.slice(i, i + 4);
        for (let step = 1; step <= STEPS; step++) {
          const t = step / STEPS;
          const u = 1 - t;
          points.push({ x: u * u * x + 2 * u * t * cx + t * t * ex, y: u * u * y + 2 * u * t * cy + t * t * ey });
        }
        x = ex;
        y = ey;
      }
    } else if (command === "C") {
      for (let i = 0; i + 5 < n.length; i += 6) {
        const [ax, ay, bx, by, ex, ey] = n.slice(i, i + 6);
        for (let step = 1; step <= STEPS; step++) {
          const t = step / STEPS;
          const u = 1 - t;
          points.push({
            x: u * u * u * x + 3 * u * u * t * ax + 3 * u * t * t * bx + t * t * t * ex,
            y: u * u * u * y + 3 * u * u * t * ay + 3 * u * t * t * by + t * t * t * ey,
          });
        }
        x = ex;
        y = ey;
      }
    } else {
      problems.push(`${describe(el)} uses the path command "${command}". Street segments may use M, L, H, V, Q and C (capital letters) only.`);
      return [];
    }
  }
  if (points.length < 2) problems.push(`${describe(el)} is not a line the sync can measure.`);
  return points;
}

/** The point halfway along, and the box around the whole line. */
function measure(points) {
  if (points.length < 2) return { mid: { x: 0, y: 0 }, box: { x: 0, y: 0, w: 0, h: 0 } };
  const lengths = points.slice(1).map((point, i) => Math.hypot(point.x - points[i].x, point.y - points[i].y));
  let remaining = lengths.reduce((sum, length) => sum + length, 0) / 2;
  let mid = points[points.length - 1];
  for (let i = 0; i < lengths.length; i++) {
    if (remaining <= lengths[i]) {
      const t = lengths[i] === 0 ? 0 : remaining / lengths[i];
      mid = { x: points[i].x + (points[i + 1].x - points[i].x) * t, y: points[i].y + (points[i + 1].y - points[i].y) * t };
      break;
    }
    remaining -= lengths[i];
  }
  const xs = points.map((point) => point.x);
  const ys = points.map((point) => point.y);
  const left = Math.min(...xs);
  const top = Math.min(...ys);
  return {
    mid: { x: round(mid.x), y: round(mid.y) },
    box: { x: round(left), y: round(top), w: round(Math.max(...xs) - left), h: round(Math.max(...ys) - top) },
  };
}

function optionalNumber(el, attribute) {
  return el.hasAttribute(attribute) ? Number(el.getAttribute(attribute)) : undefined;
}

function buildGeometry(svg) {
  const [x, y, width, height] = (svg.getAttribute("viewBox") ?? "").split(/[\s,]+/).map(Number);
  if (![x, y, width, height].every(Number.isFinite)) problems.push("The <svg> needs a viewBox of four numbers.");

  const spaces = {};
  for (const el of svg.querySelectorAll("#layer-permit-spaces rect[id][data-label]")) {
    spaces[el.getAttribute("id")] = {
      id: el.getAttribute("id"),
      x: number(el, "x"),
      y: number(el, "y"),
      w: number(el, "width"),
      h: number(el, "height"),
      capacity: optionalNumber(el, "data-capacity"),
      squareFeet: optionalNumber(el, "data-square-feet"),
    };
  }

  const segments = {};
  for (const el of svg.querySelectorAll("#layer-permit-streets path[id][data-nodes]")) {
    segments[el.getAttribute("id")] = {
      id: el.getAttribute("id"),
      d: el.getAttribute("d"),
      ...measure(samplePath(el)),
      nodes: el.getAttribute("data-nodes").trim().split(/\s+/),
      miles: optionalNumber(el, "data-miles"),
      households: optionalNumber(el, "data-households"),
    };
  }

  const nodes = {};
  for (const el of svg.querySelectorAll('#layer-route-nodes circle[id^="node-"]')) {
    nodes[el.getAttribute("id").slice("node-".length)] = { x: number(el, "cx"), y: number(el, "cy") };
  }

  if (Object.keys(spaces).length === 0) problems.push("No spaces found: #layer-permit-spaces needs <rect id data-label> shapes.");
  if (Object.keys(segments).length === 0) problems.push("No street segments found: #layer-permit-streets needs <path id data-nodes> shapes.");

  const table = (name, comment, rows) => [
    `/** ${comment} */`,
    `export const ${name} = {`,
    ...Object.entries(rows).map(([id, row]) => `  ${JSON.stringify(id)}: ${JSON.stringify(row)},`),
    "};",
    "",
  ];

  return [
    HEADER,
    "",
    "/** The drawing's coordinate box. One unit is one foot when measuring a drawn area. */",
    `export const GENERATED_VIEWBOX = ${JSON.stringify({ x, y, width, height })};`,
    "",
    ...table("GENERATED_SPACES", "One rectangle per space, with what the drawing says about it.", spaces),
    ...table("GENERATED_SEGMENTS", "One path per street segment: `d` as drawn, the point halfway along, the box around it.", segments),
    ...table("GENERATED_NODES", "Where street segments meet.", nodes),
  ].join("\n");
}

/* ---------- run ---------- */

const args = process.argv.slice(2);
const check = args.includes("--check");
const incoming = args.find((arg) => !arg.startsWith("--"));

if (incoming && !check) {
  copyFileSync(resolve(incoming), SOURCE);
  console.log(`Copied ${incoming} to ${relative(ROOT, SOURCE)}.`);
}

const palette = readPalette(readFileSync(PALETTE, "utf8"));
const dom = new JSDOM(readFileSync(SOURCE, "utf8"), { contentType: "image/svg+xml" });
const svg = dom.window.document.documentElement;

const outputs = [
  [LAYERS_OUT, buildLayers(svg, palette)],
  [GEOMETRY_OUT, buildGeometry(svg)],
];

if (problems.length > 0) {
  console.error(`The map could not be synced:\n${[...new Set(problems)].map((problem) => `  - ${problem}`).join("\n")}`);
  process.exit(1);
}

if (check) {
  const stale = outputs.filter(([path, content]) => {
    try {
      return readFileSync(path, "utf8") !== content;
    } catch {
      return true;
    }
  });
  if (stale.length > 0) {
    console.error(`Out of date: ${stale.map(([path]) => relative(ROOT, path)).join(", ")}. Run \`pnpm map:sync\`.`);
    process.exit(1);
  }
  console.log("The map's generated files are up to date.");
} else {
  for (const [path, content] of outputs) {
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(path, content);
    console.log(`Wrote ${relative(ROOT, path)}.`);
  }
}
